functions._adeEsc:
function _adeEsc(s) {
  return window._ebEsc ? window._ebEsc(s) : String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

functions._adeLoad:
function _adeLoad(storeName) {
  if (!window.eli || !window.eli.storage || typeof window.eli.storage.getAll !== "function") {
    return Promise.resolve([]);
  }
  return window.eli.storage.getAll(storeName).then(function (rows) {
    return (rows || []).filter(function (r) {
      return r && typeof r === "object" && (!r.id || String(r.id).charAt(0) !== "_");
    });
  }).catch(function () { return []; });
}

functions._adeSaveRow:
function _adeSaveRow(storeName, row) {
  if (!window.eli || !window.eli.storage || typeof window.eli.storage.put !== "function") {
    return Promise.reject(new Error("eli.storage unavailable"));
  }
  return window.eli.storage.put(storeName, row);
}

functions._adeDeleteRow:
function _adeDeleteRow(storeName, id) {
  if (!window.eli || !window.eli.storage || typeof window.eli.storage.delete !== "function") {
    return Promise.reject(new Error("eli.storage unavailable"));
  }
  return window.eli.storage.delete(storeName, id);
}

functions._adeWireRowHandlers:
function _adeWireRowHandlers(rootEl, currentTab) {
  // Save handler — pulls the latest field values from the DOM for this id
  // and writes the full row to IDB. Reads existing row first so we don't
  // strip unknown fields (forward-compat with future schema additions).
  rootEl.querySelectorAll(".ade-save").forEach(function (btn) {
    btn.onclick = function () {
      var store = btn.getAttribute("data-ade-store");
      var id = btn.getAttribute("data-ade-id");
      var rowEl = btn.closest(".ade-row");
      if (!rowEl) return;
      btn.disabled = true; var orig = btn.textContent; btn.textContent = "⏳";
      window.eli.storage.get(store, id).then(function (existing) {
        var row = existing && typeof existing === "object" ? Object.assign({}, existing) : { id: id };
        if (store === "prompts") {
          var ta = rowEl.querySelector(".ade-text");
          row.text = ta ? ta.value : "";
        } else if (store === "agreement_types") {
          var lab = rowEl.querySelector(".ade-at-label");
          var ali = rowEl.querySelector(".ade-at-aliases");
          row.label = lab ? lab.value.trim() : "";
          row.aliases = (ali ? ali.value : "").split(",")
            .map(function (a) { return a.trim(); })
            .filter(Boolean);
        }
        return _adeSaveRow(store, row);
      }).then(function () {
        btn.textContent = "✓";
        if (typeof showToast === "function") showToast("Saved " + id, "ok");
        setTimeout(function () { btn.textContent = orig; btn.disabled = false; }, 1200);
      }).catch(function (err) {
        btn.textContent = "❌";
        if (typeof showToast === "function") showToast("Save failed: " + (err && err.message || "unknown"), "err");
        setTimeout(function () { btn.textContent = orig; btn.disabled = false; }, 2000);
      });
    };
  });

  // Delete handler — confirms then removes the row from IDB + DOM.
  rootEl.querySelectorAll(".ade-del").forEach(function (btn) {
    btn.onclick = function () {
      var store = btn.getAttribute("data-ade-store");
      var id = btn.getAttribute("data-ade-id");
      if (!window.eli.ui || typeof window.eli.ui.confirm !== "function") return;
      window.eli.ui.confirm({
        variant: "danger", icon: "🗑",
        title: "Delete " + id + "?",
        message: "This removes the row from your local IDB. To remove it from all users' installs, push the section via Admin Library Publisher afterward.",
        confirmLabel: "Delete", cancelLabel: "Cancel",
      }).then(function (ok) {
        if (!ok) return;
        return _adeDeleteRow(store, id).then(function () {
          var row = btn.closest(".ade-row");
          if (row && row.parentNode) row.parentNode.removeChild(row);
          if (typeof showToast === "function") showToast("Deleted " + id, "info");
        }).catch(function (err) {
          if (typeof showToast === "function") showToast("Delete failed: " + (err && err.message || "unknown"), "err");
        });
      });
    };
  });
}

functions._adeRenderTab:
function _adeRenderTab(listEl, tabId, filterStr) {
  var store = tabId === "prompts" ? "prompts" : "agreement_types";
  var renderRow = tabId === "prompts" ? _adeRenderPromptRow : _adeRenderAgreementRow;
  listEl.innerHTML = '<div style="padding:20px; text-align:center; font-size:12px; color:#94a3b8;">⏳ Loading…</div>';
  return _adeLoad(store).then(function (rows) {
    var f = String(filterStr || "").trim().toLowerCase();
    var visible = rows.filter(function (r) {
      if (!f) return true;
      var hay = JSON.stringify(r).toLowerCase();
      return hay.indexOf(f) !== -1;
    });
    if (!visible.length) {
      listEl.innerHTML = '<div style="padding:30px; text-align:center; font-size:12px; color:#94a3b8;">' +
        (f ? "No rows match \"" + _adeEsc(f) + "\"." : "No rows in this store yet.") +
        '</div>';
      return;
    }
    listEl.innerHTML = visible.map(renderRow).join("");
    _adeWireRowHandlers(listEl, tabId);
  });
}

functions._adeNewRowPrompt:
function _adeNewRowPrompt(tabId, listEl) {
  if (!window.eli.ui || typeof window.eli.ui.prompt !== "function") return;
  var label = tabId === "prompts" ? "New prompt id" : "New agreement-type id";
  var placeholder = tabId === "prompts" ? "e.g. clauseRevise" : "e.g. Master Services Agreement";
  window.eli.ui.prompt({
    title: "Add row",
    message: label + " (must be unique):",
    placeholder: placeholder,
    confirmLabel: "Add", cancelLabel: "Cancel",
  }).then(function (id) {
    if (!id || !id.trim()) return;
    id = id.trim();
    var store = tabId === "prompts" ? "prompts" : "agreement_types";
    // Bail if an id with that name already exists.
    return window.eli.storage.get(store, id).then(function (existing) {
      if (existing) {
        if (typeof showToast === "function") showToast("'" + id + "' already exists", "warn");
        return;
      }
      var row = tabId === "prompts"
        ? { id: id, text: "" }
        : { id: id, label: id, aliases: [] };
      return _adeSaveRow(store, row).then(function () {
        if (typeof showToast === "function") showToast("Added '" + id + "'", "ok");
        var searchEl = document.getElementById("adeSearch");
        return _adeRenderTab(listEl, tabId, searchEl ? searchEl.value : "");
      });
    });
  });
}

functions.showAdminDataEditor:
function showAdminDataEditor() {
  var out = window.eli.ui.claimOutput();
  if (!out) return;
  out.classList.add("eli-view-enter");

  var header = (typeof window.createConfigHeader === "function")
    ? window.createConfigHeader("ADMIN — RESTRICTED", "📝", "Admin Data Editor", { marginBottom: "12px" })
    : (function () {
        var d = document.createElement("div");
        d.style.cssText = "padding:10px 14px; background:linear-gradient(135deg,#0d1b2a,#1b263b); color:#fff; margin-bottom:12px;";
        d.innerHTML = '<div style="font:800 9px/1 Inter,sans-serif; letter-spacing:1.2px; text-transform:uppercase; color:#c9a227;">ADMIN — RESTRICTED</div>' +
          '<div style="font:800 16px/1.2 Inter,sans-serif; margin-top:4px;">📝 Admin Data Editor</div>';
        return d;
      })();
  out.appendChild(header);

  // Intro / publish-reminder banner
  var intro = document.createElement("div");
  intro.style.cssText = "padding:10px 14px; border:1px solid #d1d5db; border-left:5px solid #7c2d12; background:#fff; margin-bottom:12px;";
  intro.innerHTML =
    '<div style="font-size:11px; color:#0f172a; line-height:1.4;">' +
      '<b>Edit AI prompts and agreement types here.</b> Changes save to your local IDB. To roll out for everyone, open ' +
      '<b>Admin Library Publisher</b> and push the corresponding section.' +
    '</div>';
  out.appendChild(intro);

  // Tabs + search row
  var tabsRow = document.createElement("div");
  tabsRow.style.cssText = "display:grid; grid-template-columns:auto auto 1fr auto; gap:8px; align-items:center; margin-bottom:10px;";
  tabsRow.innerHTML =
    '<button id="adeTabPrompts"  data-ade-tab="prompts"  class="ade-tab" style="padding:8px 14px; font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:0.4px; cursor:pointer; background:#1565c0; color:#fff; border:none; border-radius:0;">📝 AI Prompts</button>' +
    '<button id="adeTabAgree"    data-ade-tab="agreement_types" class="ade-tab" style="padding:8px 14px; font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:0.4px; cursor:pointer; background:#fff; color:#475569; border:1px solid #cbd5e1; border-radius:0;">📋 Agreement Types</button>' +
    '<input type="text" id="adeSearch" placeholder="🔍 Filter…" style="padding:7px 10px; font-size:11px; border:1px solid #cbd5e1; border-radius:0; outline:none; box-sizing:border-box;">' +
    '<button id="adeAddBtn" style="padding:8px 12px; font-size:11px; font-weight:800; cursor:pointer; background:#0f172a; color:#fff; border:none; border-radius:0;">＋ ADD</button>';
  out.appendChild(tabsRow);

  // List container
  var listEl = document.createElement("div");
  listEl.id = "adeList";
  listEl.style.cssText = "padding:4px 0;";
  out.appendChild(listEl);

  var currentTab = "prompts";
  function _setTab(tab) {
    currentTab = tab;
    var btnPrompts = document.getElementById("adeTabPrompts");
    var btnAgree = document.getElementById("adeTabAgree");
    if (btnPrompts && btnAgree) {
      var active = "background:#1565c0; color:#fff; border:none;";
      var inactive = "background:#fff; color:#475569; border:1px solid #cbd5e1;";
      var p = tab === "prompts" ? active : inactive;
      var a = tab === "agreement_types" ? active : inactive;
      btnPrompts.setAttribute("style", "padding:8px 14px; font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:0.4px; cursor:pointer; border-radius:0;" + p);
      btnAgree.setAttribute("style",   "padding:8px 14px; font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:0.4px; cursor:pointer; border-radius:0;" + a);
    }
    var searchEl = document.getElementById("adeSearch");
    _adeRenderTab(listEl, tab, searchEl ? searchEl.value : "");
  }

  document.getElementById("adeTabPrompts").onclick = function () { _setTab("prompts"); };
  document.getElementById("adeTabAgree").onclick   = function () { _setTab("agreement_types"); };
  document.getElementById("adeAddBtn").onclick     = function () { _adeNewRowPrompt(currentTab, listEl); };

  // Debounced search.
  var searchTimer = null;
  document.getElementById("adeSearch").oninput = function () {
    if (searchTimer) clearTimeout(searchTimer);
    var val = this.value;
    searchTimer = setTimeout(function () {
      _adeRenderTab(listEl, currentTab, val);
    }, 200);
  };

  _setTab("prompts");
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAdminDataEditor"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showAdminDataEditor !== "function") {
      eli.log.event("tool", "admin_data_editor_fn_missing", {});
      if (typeof showToast === "function") showToast("Admin Data Editor failed to load", "err");
      return;
    }
    try { window.showAdminDataEditor(); }
    catch (e) {
      eli.log.event("tool", "admin_data_editor_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  // HTML escape helper, inlined (consistent with admin_library_publisher).
  if (typeof window._ebEsc !== "function") {
    window._ebEsc = function (s) {
      return String(s == null ? "" : s)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    };
  }

  eli.register({
    tile: { app_admin_data_editor: _show },
    admin_data_editor: { open: _show },
  });

  eli.log.event("tool", "admin_data_editor_initialized", {});
}
